import {selectCovers} from './catalog-selection.js';
import {samplePhotos} from './sample-photos.js';
import {occasionExampleContent} from './occasion-content.js';
import {occasionTreatments,occasionDirection,occasionTreatmentName} from './gift-identity.js';
import {bookTexturePaths,resolveBookFinish} from './book-finish.js';
import {occasions} from './occasions.js';
import {cleanAppearance,appearancePalette,giftArtworkSource} from './appearance.js';
import {cleanStationery,stationeryLayouts,paintStationery,ensureStationeryFonts} from './stationery.js';
import {cleanStoryDesign,storyLayouts,drawStoryFrame} from './story-design.js';
import {cleanExperience} from './experience.js';
export const occasionFamilies={amizade:'familia',aniversario:'aniversario',aniversario_namoro:'amor',mesversario:'aniversario',casamento:'casamento',bodas:'casamento',namorados:'amor',maes:'familia',pais:'familia',avos:'familia',natal:'natal',anonovo:'conquistas',pascoa:'pascoa',formatura:'conquistas',pedido_namoro:'amor',desculpas:'amor',pet:'pet',outro:'familia'};
const directions={natal:['coral','noite','perola'],aniversario:['mel','azul','coral'],casamento:['perola','cacau','azul'],familia:['cacau','amora','ceu'],amor:['amora','perola','noite'],pascoa:['terracota','mel','ceu'],conquistas:['perola','azul','noite'],pet:['cacau','mel','terracota']};
const headlines={amizade:'Tem um pouco de nós aqui.',aniversario:'Mais um capítulo bonito.',aniversario_namoro:'Ainda bem que é com você.',mesversario:'Pequenos dias. Grandes histórias.',casamento:'O começo do nosso sim.',bodas:'O nosso sim continua.',namorados:'Meu lugar favorito é com você.',maes:'Seu carinho é casa.',pais:'Pai, a nossa história fica.',avos:'Carinho que atravessa gerações.',natal:'O melhor presente é estar perto.',anonovo:'Que venham os próximos capítulos.',pascoa:'Carinho para compartilhar.',formatura:'O futuro começa aqui.',pedido_namoro:'Vamos escrever nossa história?',desculpas:'Uma nova página para nós.',pet:'As memórias do Bento.',outro:'Um pequeno gesto. Todo o carinho.'};
export function coverOptions(occasion='amizade',format='livro'){
 if(!occasions[occasion])occasion='amizade';if(!['stories','livro','cartao','convite'].includes(format))format='livro';
 const art=occasionDirection(occasion),family=occasionFamilies[occasion],layouts=Object.entries(format==='stories'?storyLayouts:stationeryLayouts);
 return layouts.flatMap(([layout,label],i)=>directions[family].map((palette,j)=>{const background=[art.background,'cotton','frame','linen','plain'][i%5],appearance=cleanAppearance({palette,background,scene:['paper','sky','cocoa'][j],animation:['gentle','classic','confetti','float','pop','spin'][i%6],custom:true,paper:j===2?art.ink:j===1?art.soft:art.paper,ink:j===2?art.paper:art.ink,accent:j===2?art.soft:art.accent,intensity:.2,themeStyle:(i*3+j)%20,themeEffect:j===2?'sparkle':'none',coverSurface:j===1?'paper':'cloth'}),storyLayout=Object.keys(storyLayouts)[i];return {id:occasion+'-'+format+'-'+String(i*3+j+1).padStart(2,'0'),number:i*3+j+1,occasion,format,family,bookFinish:resolveBookFinish({bookFinish:{material:j===1?'paper':art.material}}),name:occasionTreatmentName(occasion,(i*3+j)%20)+' · '+label,layout,appearance,openingStyle:family,stationeryDesign:cleanStationery({layout,title:headlines[occasion],seal:true}),storyDesign:cleanStoryDesign({layout:storyLayout,palette,background,custom:true,paper:appearance.paper,ink:appearance.ink,accent:appearance.accent,title:headlines[occasion],font:j===2?'clean':'editorial',transition:['fade','slide','zoom'][j],decoration:'capy'})};}));
}
export function coverExample(cover){const family=cover.family,[photo,second]=samplePhotos(cover.occasion,(cover.number||1)-1),content=occasionExampleContent(cover.occasion,cover.format);return {...cover,...content,coverId:cover.id,coverArt:family,draftId:'catalog-example',character:'capy',person:0,texture:'algodao',pattern:'signature-0',theme:occasions[cover.occasion],color:appearancePalette(cover.appearance).accent,photo,photos:[{src:photo,caption:content.captions[0]},{src:second,caption:content.captions[1]}],pages:content.pages.map((page,i)=>({...page,photo:i===0?photo:second})),stationeryDesign:cleanStationery({...cover.stationeryDesign,title:content.title,closing:content.closing}),storyDesign:cleanStoryDesign({...cover.storyDesign,title:content.title,subtitle:content.captions[0],closing:content.closing}),experience:cleanExperience(content.experience)};}
const imageCache=new Map();async function image(src){if(!imageCache.has(src))imageCache.set(src,new Promise(resolve=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>resolve(null);i.src=src;}));return imageCache.get(src);}
export function initCoverCatalog({getState,isEditing,onApply,onPreview,onCreate}){
 const dialog=document.createElement('dialog');dialog.className='cover-catalog-dialog';dialog.setAttribute('aria-labelledby','cover-catalog-title');dialog.innerHTML='<header><div><p class="catalog-eyebrow">Coleções Capimimo</p><h2 id="cover-catalog-title">Escolha sua capa.</h2></div><button type="button" class="catalog-close" aria-label="Fechar coleção">×</button></header><p>Escolha uma base. Depois, personalize fotos, cores e cada detalhe.</p><div class="catalog-filters"><label>Ocasião<select class="catalog-occasion"></select></label><label>Formato<select class="catalog-format"><option value="livro">Livro</option><option value="cartao">Cartão</option><option value="convite">Convite</option><option value="stories">Stories</option></select></label></div><details class="catalog-extra-filters"><summary>Filtrar por composição e cores</summary><div class="catalog-filters"><label>Composição<select class="catalog-layout"><option value="all">Todas</option></select></label><label>Cores<select class="catalog-tone"><option value="all">Claras e escuras</option><option value="light">Fundos claros</option><option value="dark">Fundos escuros</option></select></label></div></details><div class="catalog-view"><button type="button" class="catalog-recommended" aria-pressed="true">Três sugestões</button><button type="button" class="catalog-all" aria-pressed="false">Ver todas as capas</button></div><p class="catalog-example-note">Exemplos ilustrativos. Suas fotos e mensagens entram na sua versão.</p><label class="catalog-preserve"><input type="checkbox" checked> Manter meus textos ao trocar de capa</label><div class="catalog-grid"></div><nav class="catalog-pagination" aria-label="Páginas da coleção"><button class="catalog-prev">← Anteriores</button><output aria-live="polite"></output><button class="catalog-next">Próximas →</button></nav>';document.body.append(dialog);
 const picker=dialog.querySelector('.catalog-occasion');for(const [key,value] of Object.entries(occasions))picker.add(new Option(value.label,key));let page=0,version=0,recommended=true,layoutFormat='',pageCount=1;
 async function render({focusResults=false}={}){const own=++version,occasion=picker.value,format=dialog.querySelector('.catalog-format').value,layoutPicker=dialog.querySelector('.catalog-layout');if(layoutFormat!==format){layoutFormat=format;layoutPicker.replaceChildren(new Option('Todas','all'));for(const[key,label]of Object.entries(format==='stories'?storyLayouts:stationeryLayouts))layoutPicker.add(new Option(label,key));}const options=selectCovers(coverOptions(occasion,format),{layout:layoutPicker.value,tone:dialog.querySelector('.catalog-tone').value,recommended});pageCount=Math.max(1,Math.ceil(options.length/6));page=Math.min(page,pageCount-1);dialog.querySelector('.catalog-recommended').setAttribute('aria-pressed',String(recommended));dialog.querySelector('.catalog-all').setAttribute('aria-pressed',String(!recommended));dialog.querySelector('.catalog-preserve').hidden=!isEditing();dialog.querySelector('.catalog-prev').disabled=page===0;dialog.querySelector('.catalog-next').disabled=page>=pageCount-1;dialog.querySelector('output').textContent=options.length?(recommended?'Sugestões para começar · '+options.length+' capas':(page*6+1)+'–'+Math.min(page*6+6,options.length)+' de '+options.length):'Nenhuma capa com estes filtros. Experimente outra composição ou cor.';const grid=dialog.querySelector('.catalog-grid');grid.replaceChildren();await ensureStationeryFonts();if(own!==version)return;
  for(const cover of options.slice(page*6,page*6+6)){const article=document.createElement('article'),canvas=document.createElement('canvas');canvas.width=cover.format==='cartao'?420:300;canvas.height=cover.format==='cartao'?300:400;canvas.setAttribute('aria-label',cover.name);const title=document.createElement('h3');title.tabIndex=-1;title.textContent=String(cover.number).padStart(2,'0')+' · '+cover.name;const preview=document.createElement('button');preview.textContent=cover.format==='stories'?'Assistir exemplo':'Experimentar em 3D';preview.addEventListener('click',()=>{dialog.close();onPreview(coverExample(cover));});const use=document.createElement('button');use.className='catalog-use';use.textContent=isEditing()?'Usar esta capa':'Criar minha versão';use.addEventListener('click',()=>{if(isEditing()){const preserve=dialog.querySelector('.catalog-preserve input').checked;onApply(cover,preserve);dialog.close();}else{dialog.close();onCreate(cover);}});article.append(canvas,title,preview,use);grid.append(article);const data=coverExample(cover);if(format==='stories'){canvas.width=270;canvas.height=480;drawStoryFrame(canvas,data,{kind:'cover'}).catch(()=>{});}else Promise.all([image(data.photo),image(giftArtworkSource(data)),image('assets/'+data.theme.sheet+'.webp'),image(data.photos[1].src),format==='livro'?image(bookTexturePaths(data.bookFinish)[0]):null]).then(([photo,pattern,sprite,other,material])=>{if(own===version)paintStationery(canvas,data,{photo,photos:[other],pattern,sprite,material});});}
  if(focusResults&&own===version&&dialog.open){const first=grid.querySelector('h3');if(first){first.focus({preventScroll:true});first.closest('article').scrollIntoView({behavior:'instant',block:'start'});}}
 }
 function open(occasion,format){const state=getState();picker.value=occasions[occasion]?occasion:state.occasion;dialog.querySelector('.catalog-format').value=format||state.format;page=0;recommended=true;layoutFormat='';dialog.querySelector('.catalog-tone').value='all';dialog.showModal();render();}
 dialog.addEventListener('close',()=>{if(!dialog.open)version++;});dialog.querySelector('.catalog-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.catalog-prev').addEventListener('click',()=>{page=Math.max(0,page-1);render({focusResults:true});});dialog.querySelector('.catalog-next').addEventListener('click',()=>{page=Math.min(pageCount-1,page+1);render({focusResults:true});});dialog.querySelector('.catalog-recommended').addEventListener('click',()=>{recommended=true;page=0;render();});dialog.querySelector('.catalog-all').addEventListener('click',()=>{recommended=false;page=0;render();});dialog.querySelectorAll('select').forEach(select=>select.addEventListener('change',()=>{page=0;if(select.matches('.catalog-layout,.catalog-tone'))recommended=false;render();}));return {open};
}
